/**
 * Durable per-session GitHub channel state.
 */
export function emptyGitHubChannelState(overrides = {}) {
    return {
        conversationKind: "pull_request",
        installationId: null,
        issueNumber: null,
        owner: "",
        pullRequestNumber: null,
        repo: "",
        repositoryId: null,
        repositoryUrl: null,
        reviewCommentId: null,
        reviewThreadRootCommentId: null,
        triggeringCommentId: null,
        deliveryId: null,
        eventName: null,
        headSha: null,
        baseRef: null,
        headRef: null,
        progressBannerCommentId: null,
        progressCheckRunId: null,
        progressCheckRunSha: null,
        progressCheckRunCompleted: null,
        ...overrides,
    };
}
/** Build binding fields for an inbound conversation. */
export function githubBindingStateForEvent(input) {
    if (input.kind === "issue") {
        return {
            conversationKind: "issue",
            installationId: input.installationId ?? null,
            issueNumber: input.number,
            owner: input.owner,
            pullRequestNumber: null,
            repo: input.repo,
            repositoryId: input.repositoryId ?? null,
            repositoryUrl: input.repositoryUrl ?? null,
            reviewCommentId: null,
            reviewThreadRootCommentId: null,
            triggeringCommentId: input.triggeringCommentId ?? null,
        };
    }
    if (input.kind === "review_thread") {
        return {
            conversationKind: "review_thread",
            installationId: input.installationId ?? null,
            issueNumber: null,
            owner: input.owner,
            pullRequestNumber: input.number,
            repo: input.repo,
            repositoryId: input.repositoryId ?? null,
            repositoryUrl: input.repositoryUrl ?? null,
            reviewCommentId: input.reviewCommentId ?? null,
            reviewThreadRootCommentId: input.reviewThreadRootCommentId ??
                input.reviewCommentId ??
                input.triggeringCommentId ??
                null,
            triggeringCommentId: input.triggeringCommentId ?? null,
        };
    }
    return {
        conversationKind: "pull_request",
        installationId: input.installationId ?? null,
        issueNumber: null,
        owner: input.owner,
        pullRequestNumber: input.number,
        repo: input.repo,
        repositoryId: input.repositoryId ?? null,
        repositoryUrl: input.repositoryUrl ?? null,
        reviewCommentId: null,
        reviewThreadRootCommentId: null,
        triggeringCommentId: input.triggeringCommentId ?? null,
    };
}
